SELECT p.id, p.title_ar, p.age_min, p.age_max, p.supervision_level, p.status, p.estimated_minutes, (SELECT s.slug FROM series s WHERE s.id=p.series_id) AS series_slug, CASE WHEN p.steps<>'[]' THEN 1 ELSE 0 END AS has_steps, (SELECT count(*) FROM asset_links al WHERE al.entity_type='project' AND al.entity_id=p.id AND al.role='cover') AS has_cover, (length(p.steps) - length(replace(p.steps,'","',''))) / 3 + CASE WHEN p.steps='[]' THEN -1 ELSE 1 END AS n_steps FROM projects p ORDER BY p.age_min, p.id;